local a=require"system.util"local b=assert(a.argparse({t=true},...))b.t=b.t or"8"if#b==0 then b[1]="-"end;local c={}if b.t:match("^%d+$")then local d=tonumber(b.t)setmetatable(c,{__index=function(e,f)return math.ceil((f+1)/d)*d-f end})elseif b.t:match("^[%d, ]+$")then local g=1;for h in b.t:gmatch"%d+"do local d=tonumber(h)assert(d>g,"expand: invalid tab stop format")for i=g,d-1 do c[i]=d-i end;g=d end;setmetatable(c,{__index=function(e,f)return 1 end})else error("expand: invalid tab stop format")end;for e,j in ipairs(b)do for k in io.lines(j~="-"and j or nil)do print(k:gsub("()\t",function(f)return(" "):rep(c[f])end))end end
